Assert.AreEqual(original.Retries, clone.Retries);

// ✅ Fix — add reference inequality + use literal expected values
var original = new Config { Timeout = 30, Retries = 3 };
var clone = original.Clone();
Assert.AreNotSame(original, clone);
Assert.AreEqual(30, clone.Timeout);
Assert.AreEqual(3, clone.Retries);
```

